import json,shutil,hashlib
from pathlib import Path
R=Path(__file__).resolve().parent
for d in ['data','logs','results']:(R/d).mkdir(exist_ok=True)
shutil.copyfile(R.parent/'jspace_relation_transfer/data/pairs.json',R/'data/pairs.json')
runtime='./llm_knowledge/.venv/bin/python'
models={
 'gemma':dict(path='models/gemma-4-12B-it',runtime=runtime,layers=[39,44],gpu=0,chat_kwargs={'enable_thinking':False},budgets=[128,512,2048],replay_budgets=[2048],turn_token='<turn|>'),
 'muse':dict(path='models/Muse-Glimmer-30B',runtime=runtime,layers=[42,48],gpu=1,chat_kwargs={'reasoning_strength':'low','current_date':'2026-10-15'},budgets=[2048,8192,16384],replay_budgets=[2048,8192,16384]),
 'glm':dict(path='models/GLM-4.1V-9B-Thinking',runtime=runtime,layers=[32,37],gpu=0,chat_kwargs={},budgets=[2048,8192,16384],replay_budgets=[2048,8192,16384]),
 'kimi':dict(path='models/Kimi-VL-A3B-Instruct',runtime='python',layers=[22,25],gpu=1,pythonpath='./jspace_more_models/kimi_runtime',chat_kwargs={},budgets=[128,512,2048],replay_budgets=[2048])}
cfg=dict(models=models,seed=20261016,ranks=[1,4],scope='4 models, each192 round1 company pairs plus984 historical pairs. Separate follow-up after user authorized fallback to preceding token. Original runs untouched.',layer_rule='round((L-1)*29/35), round((L-1)*33/35). Different architectures are not functionally matched.',boundary='Locate first target key in native final answer, never reasoning. Prefer last native token boundary after colon and before value. If no such boundary, select last token boundary preceding the token containing value onset, retaining partial field syntax for regeneration. Record exact vs preceding_token, token gap, dropped syntax. Preserve full recipient native reasoning prefix. No forced answer prefix. Missing key, missing final channel, unstable decoding, or truncated generation remain unavailable.',selection='Use all locatable development weak pairs across main/supported/swapped without correctness filtering. At least4 pairs per evidence and all4 templates required; if incomplete, label coverage-restricted exploratory SVD. Fit uncentered SVD ranks1/4 at fixed2layers. Eligible source reduction>0 and supported/swapped net correct loss<=1 each. Max absent null gain, tie rank/layer. Otherwise max mean per-evidence accuracy gain, tie rank/layer, mark nonselective. Freeze before validation/history.',gate='Original behavior gate is diagnostic only. No outcome-driven template changes.',scoring='Native reasoning/final channel separation. Primary semantic JSON removes exactly one complete outer Markdown fence; strict JSON score also retained. Never select one JSON out of several or convert string null. Invalid/truncated natural answers retained.',interventions='Forward B->D, reverse D->B, full B->D, one seeded norm-matched random, selfB/selfD. Only last position of initial prefill modified once; continue recipient computation and cache. Same material and evidence donor. All available eval pairs, report by boundary type.',success='Heldout weak main null gain>=4/16 and3/4templates, supported/swapped>=15/16 and net loss<=1, source->null>format->null, gain>random, all48validation pairs available. Coverage-limited cases cannot pass complete-coverage criterion.',truncation='Natural budgets model specific; deterministic restart at next cap, preserve attempts. Replay/self/patch share same budget ladder. Unfinished at final cap remains error/unavailable.',limits=['This follow-up is a modified intervention position protocol, not an exact replication of original PN-only experiment.','Earlier-position patch may affect punctuation and answer format. Separate source-value corrections from formatting corrections.','Muse uses same fixed native date as prior behavior run for comparability, not current calendar date.','No J-lens weights trained or transferred; causal subspace intervention only.','Native reasoning is retained and costs differ; model size alone cannot explain differences.'])
(R/'protocol.json').write_text(json.dumps(cfg,ensure_ascii=False,indent=2),encoding='utf-8')
for k in models:(R/'results'/k).mkdir(exist_ok=True)
lock={p.relative_to(R).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in [R/'protocol.json',R/'data/pairs.json',R/'run.py',R/'native.py']}
(R/'data/lock.json').write_text(json.dumps(lock,indent=2),encoding='utf-8')
print('Prepared4models1176pairs each')
